import csv
import hashlib
import io
import json
import re

SCHEMA_VERSION = "hive-structured-task-v1"
INVENTORY_SCHEMA = "grouped_inventory_v1"
CLASSIFICATION_SCHEMA = "independent_labels_v1"
MAX_SOURCE_BYTES = 2 * 1024 * 1024
MAX_INVENTORY_ROWS = 256
MAX_CLASSIFICATION_ROWS = 12
MAX_TEXT_BYTES = 2000
MAX_INTEGER = 10**9
_SHA256 = re.compile(r"^[0-9a-f]{64}$")


class StructuredMissionError(ValueError):
    pass


def sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _json_bytes(data: bytes, label: str):
    try:
        return json.loads(data.decode("utf-8-sig"), object_pairs_hook=_unique_object,
                          parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
        raise StructuredMissionError(f"{label} must be UTF-8 JSON") from exc


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate JSON object key")
        result[key] = value
    return result


def parse_output(output):
    if not isinstance(output, str):
        return None
    try:
        value = json.loads(output, object_pairs_hook=_unique_object,
                           parse_constant=lambda item: (_ for _ in ()).throw(ValueError(item)))
    except (json.JSONDecodeError, ValueError):
        return None
    return value if isinstance(value, dict) else None


def _csv_rows(data: bytes):
    try:
        text = data.decode("utf-8-sig")
        reader = csv.DictReader(io.StringIO(text, newline=""), strict=True)
        if not reader.fieldnames or len(reader.fieldnames) != len(set(reader.fieldnames)):
            raise StructuredMissionError("CSV must have unique named columns")
        rows = list(reader)
    except (UnicodeDecodeError, csv.Error) as exc:
        raise StructuredMissionError("source must be valid UTF-8 CSV") from exc
    if any(None in row or any(value is None for value in row.values()) for row in rows):
        raise StructuredMissionError("CSV rows must have exactly the declared number of fields")
    return list(reader.fieldnames), rows


def parse_source(data: bytes, source_format: str, schema_id: str):
    if not isinstance(data, bytes) or len(data) > MAX_SOURCE_BYTES:
        raise StructuredMissionError("source exceeds the 2 MiB limit")
    if source_format not in {"csv", "json"}:
        raise StructuredMissionError("source_format must be csv or json")
    if schema_id not in {INVENTORY_SCHEMA, CLASSIFICATION_SCHEMA}:
        raise StructuredMissionError("unsupported structured-data schema")
    if source_format == "csv":
        fields, rows = _csv_rows(data)
        expected = ["id", "group", "bytes"] if schema_id == INVENTORY_SCHEMA else ["id", "text"]
        if fields != expected:
            raise StructuredMissionError(f"CSV columns must be exactly {','.join(expected)} in order")
    else:
        rows = _json_bytes(data, "source")
        if not isinstance(rows, list):
            raise StructuredMissionError("JSON source must be an array of row objects")
    limit = MAX_INVENTORY_ROWS if schema_id == INVENTORY_SCHEMA else MAX_CLASSIFICATION_ROWS
    if not isinstance(rows, list) or not 0 < len(rows) <= limit:
        raise StructuredMissionError(f"source must contain 1 to {limit} rows")
    seen = set()
    checked = []
    for row in rows:
        expected = {"id", "group", "bytes"} if schema_id == INVENTORY_SCHEMA else {"id", "text"}
        if not isinstance(row, dict) or set(row) != expected:
            raise StructuredMissionError("source row does not match the pinned schema")
        row_id = row["id"]
        if not isinstance(row_id, str) or not row_id or len(row_id) > 128 or row_id in seen:
            raise StructuredMissionError("row IDs must be unique nonempty strings of at most 128 characters")
        seen.add(row_id)
        if schema_id == INVENTORY_SCHEMA:
            group = row["group"]
            raw_bytes = row["bytes"]
            if not isinstance(group, str) or not group or len(group) > 128:
                raise StructuredMissionError("inventory groups must be nonempty strings of at most 128 characters")
            if source_format == "csv":
                if not isinstance(raw_bytes, str) or not re.fullmatch(r"(?:0|[1-9][0-9]{0,9})", raw_bytes):
                    raise StructuredMissionError("bytes must be a canonical nonnegative decimal integer")
                raw_bytes = int(raw_bytes)
            if type(raw_bytes) is not int or not 0 <= raw_bytes <= MAX_INTEGER:
                raise StructuredMissionError("bytes must be an integer between 0 and 1,000,000,000")
            checked.append({"id": row_id, "group": group, "bytes": raw_bytes})
        else:
            text = row["text"]
            if not isinstance(text, str) or not 0 < len(text) <= MAX_TEXT_BYTES:
                raise StructuredMissionError("classification text must contain 1 to 2,000 characters")
            checked.append({"id": row_id, "text": text})
    return checked


def inventory_result(rows):
    groups = {}
    for row in rows:
        current = groups.setdefault(row["group"], {"count": 0, "bytes": 0})
        current["count"] += 1
        current["bytes"] += row["bytes"]
    return {"groups": dict(sorted(groups.items()))}


def validate_labels(labels, rows):
    if (not isinstance(labels, list) or not 2 <= len(labels) <= 12
            or any(not isinstance(label, str) or not label or len(label) > 128 for label in labels)
            or len(set(labels)) != len(labels)):
        raise StructuredMissionError("labels must be 2 to 12 unique nonempty strings")
    return labels


def parse_oracle(data: bytes, schema_id: str, rows: list[dict], labels=None):
    if len(data) > 64 * 1024:
        raise StructuredMissionError("oracle exceeds the 64 KiB limit")
    value = _json_bytes(data, "oracle")
    if schema_id == INVENTORY_SCHEMA:
        if not isinstance(value, dict) or set(value) != {"groups"} or value != inventory_result(rows):
            raise StructuredMissionError("inventory oracle must exactly reproduce source counts and byte sums")
        return value
    allowed = set(validate_labels(labels, rows))
    expected_ids = {row["id"] for row in rows}
    if (not isinstance(value, dict) or set(value) != {"labels"} or not isinstance(value["labels"], dict)
            or set(value["labels"]) != expected_ids
            or any(not isinstance(label, str) or label not in allowed for label in value["labels"].values())):
        raise StructuredMissionError("classification oracle must label every source row with an allowed label")
    return value


def field_verdicts(schema_id: str, rows: list[dict], expected: dict, actual: dict | None):
    if schema_id == INVENTORY_SCHEMA:
        verdicts = {"source_schema": True, "groups": {}}
        expected_groups = expected.get("groups", {})
        actual_groups = actual.get("groups", {}) if isinstance(actual, dict) else {}
        for group, record in expected_groups.items():
            observed = actual_groups.get(group)
            if not isinstance(observed, dict):
                observed = {}
            verdicts["groups"][group] = {
                "count": observed.get("count") == record["count"],
                "bytes": observed.get("bytes") == record["bytes"],
            }
        return verdicts
    expected_labels = expected.get("labels", {})
    actual_labels = actual.get("labels", {}) if isinstance(actual, dict) else {}
    return {"source_schema": True, "labels": {
        row["id"]: actual_labels.get(row["id"]) == expected_labels.get(row["id"])
        for row in rows}}


def output_matches(schema_id: str, rows: list[dict], expected: dict, actual: dict):
    verdicts = field_verdicts(schema_id, rows, expected, actual)
    if schema_id == INVENTORY_SCHEMA:
        return bool(verdicts["source_schema"] and all(
            all(fields.values()) for fields in verdicts["groups"].values())) and actual == expected
    return bool(verdicts["source_schema"] and all(verdicts["labels"].values())) and actual == expected

"""M1 inventory: typed views over structured_verifier (protocol §3). Views add only type adaptation and input checks.
This whole file is inlined into the container candidate, so keep imports to stdlib + the one stripped line below."""
import base64, csv, hashlib, io, json

# Types: Source={"format","bytes"}; Rows=List[Row]; Report=dict. Strings are canonical type names.
TYPES = {"identity": ("Source", "Source"), "parse_whole": ("Source", "List[Row]"),
         "split_rows": ("Source", "List[Source]"), "aggregate": ("List[Row]", "Report")}
HEADER = ["id", "group", "bytes"]


def make_source(fmt, data):
    return {"format": fmt, "bytes": data}


def _check_source(src):
    if not (isinstance(src, dict) and set(src) == {"format", "bytes"} and isinstance(src["bytes"], bytes)):
        raise TypeError("input must be a Source {format, bytes}")
    if src["format"] not in ("csv", "json"):
        raise StructuredMissionError("source_format must be csv or json")
    if len(src["bytes"]) > MAX_SOURCE_BYTES:
        raise StructuredMissionError("source exceeds the 2 MiB limit")


def identity(src):
    return src


def parse_whole(src):
    _check_source(src)
    return parse_source(src["bytes"], src["format"], INVENTORY_SCHEMA)


def split_rows(src):
    _check_source(src)
    if src["format"] == "csv":
        fields, rows = _csv_rows(src["bytes"])
        if fields != HEADER:
            raise StructuredMissionError("CSV columns must be exactly id,group,bytes in order")
        out = []
        for row in rows:
            buf = io.StringIO(newline="")
            w = csv.writer(buf, lineterminator="\n")
            w.writerow(fields)
            w.writerow([row[f] for f in fields])
            out.append(make_source("csv", buf.getvalue().encode("utf-8")))
        return out
    rows = _json_bytes(src["bytes"], "source")
    if not isinstance(rows, list):
        raise StructuredMissionError("JSON source must be an array of row objects")
    return [make_source("json", json.dumps([el], ensure_ascii=True).encode("utf-8")) for el in rows]


def aggregate(rows):
    return inventory_result(rows)


PRIMS = {"identity": identity, "parse_whole": parse_whole, "split_rows": split_rows, "aggregate": aggregate}


def is_list_type(t):
    return t.startswith("List[")


def each_type(p_name):
    """Type of each(p): List[X] -> List[Y], flattened when Y is a list type."""
    x, y = TYPES[p_name]
    return "List[" + x + "]", (y if is_list_type(y) else "List[" + y + "]")


def each(p):
    """each(p)(xs, errors): applies p per element; StructuredMissionError -> errors.append((i, str(e))); anything else propagates."""
    flat = is_list_type(TYPES[p.__name__][1])

    def run(xs, errors):
        out = []
        for i, x in enumerate(xs):
            try:
                y = p(x)
            except StructuredMissionError as e:
                errors.append((i, str(e)))
                continue
            if flat:
                out.extend(y)
            else:
                out.append(y)
        return out
    return run


def inventory():
    import inspect
    sha = lambda f: hashlib.sha256(inspect.getsource(f).encode()).hexdigest()
    wraps = {"identity": [], "parse_whole": [parse_source, _json_bytes, _csv_rows, _unique_object],
             "split_rows": [_csv_rows, _json_bytes, _unique_object], "aggregate": [inventory_result]}
    pins = {n: {"pin": sha(PRIMS[n]), "wraps": {f.__name__: sha(f) for f in wraps[n]}} for n in PRIMS}
    pins["each"] = {"pin": sha(each), "wraps": {}}
    return pins


def run_workflow(steps, src):
    """Execute a validated step list; returns (value, errors). Errors outside each propagate (whole-source failure)."""
    value, errors = src, []
    for s in steps:
        if s.startswith("each("):
            value = each(PRIMS[s[5:-1]])(value, errors)
        else:
            value = PRIMS[s](value)
    return value, errors


def canonical_output(steps, src):
    """§2 canonical output with the §3.1 error channel; any uncaptured failure -> source_rejected."""
    try:
        report, errors = run_workflow(steps, src)
        out = dict(report)
        out["quarantined"] = [{"index": i, "reason": r} for i, r in sorted(errors, key=lambda e: e[0])]
    except Exception:
        out = {"error": "source_rejected"}
    return json.dumps(out, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def container_apply(steps, text):
    env = json.loads(text)
    one = lambda e: canonical_output(steps, make_source(e["format"], base64.b64decode(e["source_b64"])))
    return json.dumps([one(e) for e in env]) if isinstance(env, list) else one(env)  # list envelope = batch: JSON list of canonical outputs

"""M2 inventory (protocol §3): M1's views and `each`, plus one declared-preparation view, `to_json`.
Inlined into the container candidate after m1_views, so imports from M1 carry the inline-strip marker and
rebinding TYPES/PRIMS in the flat namespace makes M1's `each` see `to_json`."""
import hashlib, itertools, json

TYPES = dict(TYPES, to_json=("List[Row]", "Source"))


def to_json(rows):
    return {"format": "json", "bytes": json.dumps(rows, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode("utf-8")}


PRIMS = dict(PRIMS, to_json=to_json)


def each_type(p_name):
    """Type of each(p) over the M2 TYPES: List[X] -> List[Y], flattened when Y is a list type."""
    x, y = TYPES[p_name]
    return "List[" + x + "]", (y if is_list_type(y) else "List[" + y + "]")


def run_workflow(steps, src):
    """Execute a validated step list; returns (value, errors). Errors outside each propagate."""
    value, errors = src, []
    for s in steps:
        if s.startswith("each("):
            value = each(PRIMS[s[5:-1]])(value, errors)
        else:
            value = PRIMS[s](value)
    return value, errors


def inventory():
    import inspect
    from . import m1_views
    pins = m1_views.inventory()
    pins["to_json"] = {"pin": hashlib.sha256(inspect.getsource(to_json).encode()).hexdigest(), "wraps": {}}
    return pins


def symbols():
    return list(TYPES) + [f"each({n})" for n in TYPES]


def symbol_type(sym):
    """(in_type, out_type) of a symbol, or None when unknown / too deep."""
    if sym in TYPES:
        return TYPES[sym]
    if isinstance(sym, str) and sym.startswith("each(") and sym.endswith(")") and sym[5:-1] in TYPES:
        return each_type(sym[5:-1])
    return None


def type_check(steps, in_type, out_type):
    """None if `steps` is a legal 1..3 step list from in_type to out_type; else the refusal reason."""
    if not isinstance(steps, list) or not 1 <= len(steps) <= 3:
        return "steps must be a list of 1..3"
    cur = in_type
    for s in steps:
        t = symbol_type(s)
        if t is None:
            return f"unknown or too deep symbol {s!r}"
        if t[0] != cur:
            return f"type error at {s!r}: expected {t[0]}, have {cur}"
        cur = t[1]
    return None if cur == out_type else f"workflow ends in {cur}, must end in {out_type}"


def enumerate_legal(in_type, out_type):
    out = [list(t) for n in range(1, 4) for t in itertools.product(symbols(), repeat=n) if type_check(list(t), in_type, out_type) is None]
    return sorted(out, key=lambda s: (len(s), s))


def all_lists():
    return [list(t) for n in range(1, 4) for t in itertools.product(symbols(), repeat=n)]

def project_R(steps, src):
    try:
        value, errors = run_workflow(steps, src)
        out = {"converted": value["bytes"].decode("utf-8"), "quarantined": [{"index": i, "reason": r} for i, r in sorted(errors, key=lambda e: e[0])]}
    except Exception:
        out = {"error": "source_rejected"}
    return json.dumps(out, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def project_C(steps, files):
    srcs = [make_source(f["format"], f["text"].encode("utf-8")) for f in files]
    try:
        report, errors = run_workflow(steps, srcs)
        out = dict(report)
        out["quarantined"] = [{"index": i, "reason": r} for i, r in sorted(errors, key=lambda e: e[0])]
    except Exception:
        out = {"error": "source_rejected"}
    return json.dumps(out, sort_keys=True, separators=(",", ":"), ensure_ascii=True)


def container_apply(steps, text):
    env = json.loads(text)
    one = lambda e: project_C(steps, e["files"]) if "files" in e else project_R(steps, make_source(e["format"], base64.b64decode(e["source_b64"])))
    return json.dumps([one(e) for e in env]) if isinstance(env, list) else one(env)


STEPS = ['parse_whole', 'to_json']

def apply(text, checks):
    return container_apply(STEPS, text)

